import json, math, re, sys
# Independent frame-by-frame model of termpixel_pong written from the documented rules (80x80 canvas, paddle 2x12 at x=5 / x=73 starting y=34,
# paddle speed 100 px/s, ball 2x2 at speed 80 px/s growing 5 % per paddle hit up to 150, serve delay 1 s, ai retarget every 0.1 s with the
# difficulty table easy/medium/hard, xorshift32 generator owned by the program, dt clamped to 0.1 s) driven by the virtual clock that
# clockinj.py supplies (frame f is read at T0 + f/fps exactly). It compares every output frame of the build under test with the model,
# ignoring the text overlays (score digits, legends, SERVING, GAME OVER banners).
cfg = json.load(open(sys.argv[1]))
FPS, NF, SEED, WIN = cfg['fps'], cfg['frames'], cfg['seed'], cfg['winning']
AI = cfg.get('ai')
TWO = AI is None
KEYS = {int(k): bytes.fromhex(v) for k, v in cfg.get('keys', {}).items()}
W = H = 80
PW, PH, PSPEED, BALL, BSPEED, BMAX, SERVE = 2, 12, 100.0, 2, 80.0, 150.0, 1.0
TABLE = {'easy': (0.6, 0.7, 8), 'medium': (0.8, 0.85, 4), 'hard': (1.0, 0.95, 2)}
class Rng:
    def __init__(self, s): self.s = s if s else 1
    def next(self):
        x = self.s
        x ^= (x << 13) & 0xffffffff; x ^= x >> 17; x ^= (x << 5) & 0xffffffff
        self.s = x
        return x
    def uniform(self, lo, hi):
        return lo + (hi - lo) * ((self.next() & 0xffffff) / 16777216.0)
class G: pass
def serve(g, d, rng):
    g.bx, g.by, g.bspeed = W / 2.0, H / 2.0, BSPEED
    ang = rng.uniform(-45, 45) * math.pi / 180.0
    g.bvx = d * g.bspeed * math.cos(ang); g.bvy = g.bspeed * math.sin(ang)
    g.serving, g.serve_t = 1, 0.0
def init(rng):
    g = G()
    g.lx, g.ly, g.rx, g.ry = 5.0, H / 2.0 - 6, float(W - 7), H / 2.0 - 6
    g.ls = g.rs = 0; g.paused = g.over = 0; g.ai_target = 0.0; g.ai_timer = 0.0
    serve(g, +1, rng)
    return g
def clamp(v, lo, hi): return lo if v < lo else (hi if v > hi else v)
def aabb(ax, ay, aw, ah, bx, by, bw, bh): return ax < bx + bw and ax + aw > bx and ay < by + bh and ay + ah > by
def bounce(g, py, d):
    hit = clamp((g.by + BALL / 2.0 - py) / float(PH), 0, 1)
    ang = (hit - 0.5) * 2.0 * 60.0 * math.pi / 180.0
    g.bspeed *= 1.05
    if g.bspeed > BMAX: g.bspeed = BMAX
    g.bvx = d * g.bspeed * math.cos(ang); g.bvy = g.bspeed * math.sin(ang)
def update(g, dt, ul, dl, ur, dr, rng):
    if g.paused or g.over: return
    if ul: g.ly -= PSPEED * dt
    if dl: g.ly += PSPEED * dt
    if TWO:
        if ur: g.ry -= PSPEED * dt
        if dr: g.ry += PSPEED * dt
    else:
        react, acc, margin = TABLE[AI]
        g.ai_timer += dt
        if g.ai_timer >= 0.1:
            g.ai_timer = 0
            pred = g.by
            if rng.uniform(0, 1) > acc:
                pred += rng.uniform(-margin, margin)
            g.ai_target = pred - PH / 2.0
        diff = g.ai_target - g.ry
        step = PSPEED * react * dt
        if abs(diff) <= step: g.ry = g.ai_target
        else: g.ry += step if diff > 0 else -step
    g.ly = clamp(g.ly, 0, H - PH); g.ry = clamp(g.ry, 0, H - PH)
    if g.serving:
        g.serve_t += dt
        if g.serve_t < SERVE: return
        g.serving = 0
    g.bx += g.bvx * dt; g.by += g.bvy * dt
    if g.by <= 0: g.by = 0; g.bvy = -g.bvy
    if g.by >= H - BALL: g.by = H - BALL; g.bvy = -g.bvy
    if g.bvx < 0 and aabb(g.bx, g.by, BALL, BALL, g.lx, g.ly, PW, PH):
        g.bx = g.lx + PW; bounce(g, g.ly, +1)
    if g.bvx > 0 and aabb(g.bx, g.by, BALL, BALL, g.rx, g.ry, PW, PH):
        g.bx = g.rx - BALL; bounce(g, g.ry, -1)
    if g.bx + BALL < 0:
        g.rs += 1
        if g.rs >= WIN: g.over = 1
        else: serve(g, +1, rng)
    elif g.bx > W:
        g.ls += 1
        if g.ls >= WIN: g.over = 1
        else: serve(g, -1, rng)
def trunc(v): return int(v)
def render(g):
    px = {}
    def rect(x, y, w, h, c):
        for yy in range(y, y + h):
            for xx in range(x, x + w):
                if 0 <= xx < W and 0 <= yy < H: px[(xx, yy)] = c
    for y in range(0, H, 4): rect(W // 2 - 1, y, 2, 2, (120, 120, 120))
    rect(trunc(g.lx), trunc(g.ly), PW, PH, (255, 255, 255))
    rect(trunc(g.rx), trunc(g.ry), PW, PH, (255, 255, 255))
    rect(trunc(g.bx), trunc(g.by), BALL, BALL, (255, 255, 255))
    return px
def parse_keys(b):
    out, i = [], 0
    while i < len(b):
        c = b[i]
        if c == 0x1b:
            if b[i + 1:i + 3] == b'[A': out.append('UP'); i += 3; continue
            if b[i + 1:i + 3] == b'[B': out.append('DOWN'); i += 3; continue
            out.append('ESC'); i += 1; continue
        out.append('ENTER' if c in (10, 13) else chr(c)); i += 1
    return out
def simulate(reseed=True):
    rng = Rng(SEED)
    g = init(rng)
    frames, T0 = [], (1000, 0)
    prev = now = T0
    deadline = list(T0)
    fns = 1000000000 // FPS
    for f in range(NF):
        ul = dl = ur = dr = 0
        for k in parse_keys(KEYS.get(f, b'')):
            if k == 'p': g.paused = not g.paused
            elif k == 'ENTER' and g.over:
                if reseed: rng = Rng(SEED)
                g = init(rng)
            elif k == 'w': ul, dl = 1, 0
            elif k == 's': dl, ul = 1, 0
            elif k == 'UP': ur, dr = 1, 0
            elif k == 'DOWN': dr, ur = 1, 0
        now = tuple(deadline)
        dt = (now[0] - prev[0]) + (now[1] - prev[1]) / 1e9
        prev = now
        if dt > 0.1: dt = 0.1
        update(g, dt, ul, dl, ur, dr, rng)
        frames.append((render(g), g.serving, g.over, g.ls, g.rs))
        deadline[1] += fns
        if deadline[1] >= 1000000000: deadline[1] -= 1000000000; deadline[0] += 1
    return frames
def decode(data):
    out = []
    for chunk in data.split(b'\x1b[H')[1:]:
        px, y = {}, 0
        for row in chunk.split(b'\x1b[0m\n'):
            if not row: continue
            fg = bg = (0, 0, 0); i = 0; x = 0
            while i < len(row):
                m = re.match(rb'\x1b\[([34])8;2;(\d+);(\d+);(\d+)m', row[i:])
                if m:
                    c = (int(m.group(2)), int(m.group(3)), int(m.group(4)))
                    if m.group(1) == b'3': fg = c
                    else: bg = c
                    i += m.end(); continue
                if row[i:i + 1] == b' ':
                    px[(x, y)] = bg; px[(x, y + 1)] = bg; x += 1; i += 1
                elif row[i:i + 3] == b'\xe2\x96\x80':
                    px[(x, y)] = fg; px[(x, y + 1)] = bg; x += 1; i += 3
                else:
                    raise SystemExit('undecodable byte %r' % row[i:i + 4])
            y += 2
        out.append(px)
    return out
def masked(f, serving, over):
    m = set()
    for y in range(10):
        for x in range(W): m.add((x, y))
    if serving:
        for y in range(34, 41):
            for x in range(20, 62): m.add((x, y))
    if over:
        for y in list(range(29, 36)) + list(range(39, 46)) + list(range(49, 56)):
            for x in range(14, 68): m.add((x, y))
    return m
def mismatches(cand, model):
    bad = 0; first = None
    for f, (cpx, (mpx, serving, over, _l, _r)) in enumerate(zip(cand, model)):
        mask = masked(f, serving, over)
        for y in range(H):
            for x in range(W):
                if (x, y) in mask: continue
                if cpx.get((x, y), (0, 0, 0)) != mpx.get((x, y), (0, 0, 0)):
                    bad += 1
                    if first is None: first = (f, x, y)
    return bad, first
cand = decode(open('frames.out', 'rb').read())
model = simulate(True)
res = ['frames=%s' % ('ok' if len(cand) == NF else 'got-%d-of-%d' % (len(cand), NF))]
bad, first = mismatches(cand, model)
res.append('pixels=%s' % ('exact' if bad == 0 else 'mismatch-%d-first-%s' % (bad, first)))
# facts derived from the model that the case is expected to exercise
def ball_start(frames):
    for f, fr in enumerate(frames):
        px = fr[0] if isinstance(fr, tuple) else fr
        if px.get((40, 40)) != (255, 255, 255) or px.get((41, 41)) != (255, 255, 255): return f
    return None
res.append('serve_move_frame_model=%s serve_move_frame_candidate=%s' % (ball_start(model), ball_start(cand)))
res.append('final_score_model=%d-%d' % (model[-1][3], model[-1][4]))
res.append('game_over_model=%d' % model[-1][2])
if cfg.get('alt_no_reseed'):
    alt = simulate(False)
    abad, _ = mismatches(cand, alt)
    res.append('alt_model_without_reseed=%s' % ('differs' if abad else 'same'))
if AI is not None:
    keep = AI
    diffs = []
    for other in TABLE:
        if other == keep: continue
        AI = other
        ob, _ = mismatches(cand, simulate(True))
        diffs.append('differs' if ob else 'same')
    AI = keep
    res.append('other_difficulty_models=%s' % ','.join(diffs))
open('result', 'w').write('\n'.join(res) + '\n')

