    while i < len(b):
        c = b[i]
        if c == 0x1b:
            if b[i + 1:i + 3] == b'[A': out.append('UP'); i += 3; continue
            if b[i + 1:i + 3] == b'[B': out.append('DOWN'); i += 3; continue
            out.append('ESC'); i += 1; continue
        out.append('ENTER' if c in (10, 13) else chr(c)); i += 1
    return out
def simulate(reseed=True):
    rng = Rng(SEED)
    g = init(rng)
    frames, T0 = [], (1000, 0)
    prev = now = T0
    deadline = list(T0)
    fns = 1000000000 // FPS
    for f in range(NF):
        ul = dl = ur = dr = 0
        for k in parse_keys(KEYS.get(f, b'')):
            if k == 'p': g.paused = not g.paused
            elif k == 'ENTER' and g.over:
                if reseed: rng = Rng(SEED)
                g = init(rng)
            elif k == 'w': ul, dl = 1, 0
            elif k == 's': dl, ul = 1, 0
            elif k == 'UP': ur, dr = 1, 0
            elif k == 'DOWN': dr, ur = 1, 0
        now = tuple(deadline)
        dt = (now[0] - prev[0]) + (now[1] - prev[1]) / 1e9
        prev = now
        if dt > 0.1: dt = 0.1
        update(g, dt, ul, dl, ur, dr, rng)
        frames.append((render(g), g.serving, g.over, g.ls, g.rs))
        deadline[1] += fns
        if deadline[1] >= 1000000000: deadline[1] -= 1000000000; deadline[0] += 1
    return frames
def decode(data):
    out = []
    for chunk in data.split(b'\x1b[H')[1:]:
        px, y = {}, 0
        for row in chunk.split(b'\x1b[0m\n'):
            if not row: continue
            fg = bg = (0, 0, 0); i = 0; x = 0
            while i < len(row):
                m = re.match(rb'\x1b\[([34])8;2;(\d+);(\d+);(\d+)m', row[i:])
                if m:
                    c = (int(m.group(2)), int(m.group(3)), int(m.group(4)))
                    if m.group(1) == b'3': fg = c
                    else: bg = c
                    i += m.end(); continue
                if row[i:i + 1] == b' ':
                    px[(x, y)] = bg; px[(x, y + 1)] = bg; x += 1; i += 1
                elif row[i:i + 3] == b'\xe2\x96\x80':
                    px[(x, y)] = fg; px[(x, y + 1)] = bg; x += 1; i += 3
                else:
                    raise SystemExit('undecodable byte %r' % row[i:i + 4])
            y += 2
        out.append(px)
    return out
def masked(f, serving, over):
    m = set()
    for y in range(10):
        for x in range(W): m.add((x, y))
    if serving:
        for y in range(34, 41):
            for x in range(20, 62): m.add((x, y))
    if over:
        for y in list(range(29, 36)) + list(range(39, 46)) + list(range(49, 56)):
            for x in range(14, 68): m.add((x, y))
    return m
def mismatches(cand, model):
    bad = 0; first = None
    for f, (cpx, (mpx, serving, over, _l, _r)) in enumerate(zip(cand, model)):
        mask = masked(f, serving, over)
        for y in range(H):
            for x in range(W):
                if (x, y) in mask: continue
                if cpx.get((x, y), (0, 0, 0)) != mpx.get((x, y), (0, 0, 0)):
                    bad += 1
                    if first is None: first = (f, x, y)
    return bad, first
