# facts derived from the model that the case is expected to exercise
def ball_start(frames):
    for f, fr in enumerate(frames):
        px = fr[0] if isinstance(fr, tuple) else fr
        if px.get((40, 40)) != (255, 255, 255) or px.get((41, 41)) != (255, 255, 255): return f
    return None
res.append('serve_move_frame_model=%s serve_move_frame_candidate=%s' % (ball_start(model), ball_start(cand)))
res.append('final_score_model=%d-%d' % (model[-1][3], model[-1][4]))
